export function authInterceptor(
  req: HttpRequest<unknown>,
  next: HttpHandlerFn,
): Observable<HttpEvent<unknown>> {
  const token = inject(AuthService).token();
  return next(req.clone({ headers: req.headers.set('Authorization', `Bearer ${token}`) }));
}

